#include <stdio.h>

int main() {
    int burst[] = {5, 3, 2};
    int remaining[] = {5, 3, 2};
    int finish[3] = {0};
    int quantum = 2, time = 0, done = 0;
    while (done < 3) {
        for (int i = 0; i < 3; i++) {
            if (remaining[i] > 0) {
                int slice = remaining[i] < quantum ? remaining[i] : quantum;
                time += slice;
                remaining[i] -= slice;
                if (remaining[i] == 0) {
                    finish[i] = time;
                    done++;
                }
            }
        }
    }
    for (int i = 0; i < 3; i++) {
        printf("P%d finishes at %d, waits %d\n", i + 1, finish[i], finish[i] - burst[i]);
    }
    return 0;
}
